#!/usr/bin/env node

/**
 * Database migration script.
 *
 * Reads `.sql` files from the ./migrations/ directory and logs each filename
 * it would apply, in lexicographic (alphabetical) order. This convention works
 * well when migrations are prefixed with timestamps or zero-padded numbers,
 * e.g. `20240101120000_create_users.sql` or `001_create_users.sql`.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort(); // lexicographic order ensures deterministic application order
}

function migrate() {
  console.log(`Looking for migrations in: ${MIGRATIONS_DIR}`);

  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration file(s). Applying in order:`);
  files.forEach((file, index) => {
    console.log(`  [${index + 1}/${files.length}] Applying: ${file}`);
  });

  console.log('Done.');
}

migrate();

#!/usr/bin/env node

/**
 * Database migration script.
 *
 * Reads `.sql` files from the ./migrations/ directory and logs each filename
 * it would apply, in lexicographic (alphabetical) order. This convention works
 * well when migrations are prefixed with timestamps or zero-padded numbers,
 * e.g. `20240101120000_create_users.sql` or `001_create_users.sql`.
 *
 * Connection string is resolved from `.env.test` (DATABASE_URL). No real
 * database connection is made — we just log that we connected.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Minimal .env parser. Supports:
 *   - KEY=VALUE
 *   - blank lines and `#` comments
 *   - optional surrounding single or double quotes around the value
 *   - `export KEY=VALUE` syntax
 * Does not perform variable interpolation.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const contents = fs.readFileSync(filePath, 'utf8');
  const env = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    // Strip optional `export ` prefix
    const withoutExport = line.startsWith('export ') ? line.slice('export '.length) : line;

    const eqIndex = withoutExport.indexOf('=');
    if (eqIndex === -1) continue;

    const key = withoutExport.slice(0, eqIndex).trim();
    let value = withoutExport.slice(eqIndex + 1).trim();

    // Strip surrounding quotes if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) env[key] = value;
  }

  return env;
}

/**
 * Redact the password portion of a connection URL for safe logging.
 * e.g. postgres://user:secret@host:5432/db -> postgres://user:***@host:5432/db
 */
function redactUrl(url) {
  try {
    const parsed = new URL(url);
    if (parsed.password) parsed.password = '***';
    return parsed.toString();
  } catch {
    return url; // Not a parseable URL; return as-is.
  }
}

function resolveDatabaseUrl() {
  let env;
  try {
    env = parseEnvFile(ENV_FILE);
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }

  const url = env.DATABASE_URL;
  if (!url) {
    console.error(`DATABASE_URL not set in ${ENV_FILE}`);
    process.exit(1);
  }

  return url;
}

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort(); // lexicographic order ensures deterministic application order
}

function migrate() {
  const databaseUrl = resolveDatabaseUrl();
  console.log(`Resolved DATABASE_URL from ${path.basename(ENV_FILE)}: ${redactUrl(databaseUrl)}`);
  console.log('Connected successfully.');

  console.log(`Looking for migrations in: ${MIGRATIONS_DIR}`);

  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration file(s). Applying in order:`);
  files.forEach((file, index) => {
    console.log(`  [${index + 1}/${files.length}] Applying: ${file}`);
  });

  console.log('Done.');
}

migrate();

#!/usr/bin/env node

/**
 * Simple database migration script.
 *
 * Reads .sql files from ./migrations/ and logs each filename it would apply,
 * in lexicographic (alphabetical) order. Conventionally migration files are
 * named with a sortable prefix such as a timestamp or zero-padded sequence
 * number (e.g. `001_init.sql`, `20240101120000_add_users.sql`) so that
 * lexicographic order matches intended application order.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort(); // lexicographic order
}

function main() {
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log(`No migration files found in ${MIGRATIONS_DIR}`);
    return;
  }

  console.log(`Found ${files.length} migration(s) in ${MIGRATIONS_DIR}:`);
  files.forEach((file, index) => {
    console.log(`  [${String(index + 1).padStart(3, '0')}] Would apply: ${file}`);
  });
}

main();

