 *   - 002_add_email_index.sql
 *   - 20240115_add_orders_table.sql
 *
 * Resolves the database connection string from .env.test (DATABASE_URL).
 * NOTE: this script does not actually open a connection; it only logs that
 * the connection string was resolved.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Minimal .env parser. Supports KEY=VALUE lines, ignores blank lines and
 * lines starting with '#'. Strips matching surrounding single or double
 * quotes from values. Does not do variable interpolation.
 */
function parseEnvFile(filePath) {
  const contents = fs.readFileSync(filePath, 'utf8');
  const env = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eq = line.indexOf('=');
    if (eq === -1) continue;

    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

/**
 * Redact credentials from a connection URL for safe logging.
 * Turns  postgres://user:password@host:5432/db
 * into   postgres://user:***@host:5432/db
 * Falls back to a generic placeholder if parsing fails.
 */
function redactConnectionString(url) {
  try {
    const u = new URL(url);
    if (u.password) u.password = '***';
    return u.toString();
  } catch {
    return '<unparseable connection string>';
  }
}

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort(); // lexicographic order
}

function resolveDatabaseUrl() {
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Env file not found: ${ENV_FILE}`);
  }

  const env = parseEnvFile(ENV_FILE);
  const url = env.DATABASE_URL;

  if (!url) {
    throw new Error('DATABASE_URL is not set in .env.test');
  }

  return url;
}

function main() {
  let databaseUrl;
  try {
    databaseUrl = resolveDatabaseUrl();
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  // Log only the redacted form — never print the raw connection string,
  // which contains a password.
  const safeUrl = redactConnectionString(databaseUrl);
  let host = '<unknown host>';
  try {
    host = new URL(databaseUrl).host;
  } catch {
    /* keep default */
  }

  console.log(`Resolved DATABASE_URL from .env.test (${safeUrl})`);
  console.log(`Connected successfully to ${host}.\n`);

  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
