#!/usr/bin/env node

/**
 * Database migration script.
 *
 * Reads DATABASE_URL from ./.env.test, then reads SQL files from the
 * ./migrations/ directory and logs each filename it would apply, in
 * lexicographic (alphabetical) order.
 *
 * Convention: name your migration files with a sortable prefix, e.g.:
 *   001_create_users.sql
 *   002_add_email_index.sql
 *   20240115T120000_add_orders.sql
 */

const fs = require('fs');
const path = require('path');

const ENV_FILE = path.join(__dirname, '.env.test');
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Minimal .env parser. Supports:
 *   - KEY=value
 *   - optional `export ` prefix
 *   - single- or double-quoted values
 *   - # comments (full-line and trailing on unquoted values)
 *   - blank lines
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file does not exist: ${filePath}`);
  }

  const contents = fs.readFileSync(filePath, 'utf8');
  const env = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const match = line.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!match) continue;

    const key = match[1];
    let value = match[2].trim();

    // Quoted value: strip quotes, keep inner content as-is.
    if (
      (value.startsWith('"') && value.endsWith('"') && value.length >= 2) ||
      (value.startsWith("'") && value.endsWith("'") && value.length >= 2)
    ) {
      value = value.slice(1, -1);
    } else {
      // Unquoted: strip trailing inline comment.
      const hashIdx = value.indexOf(' #');
      if (hashIdx !== -1) value = value.slice(0, hashIdx).trim();
    }

    env[key] = value;
  }

  return env;
}

/** Mask credentials in a connection URL for safe logging. */
function redactUrl(url) {
  try {
    const u = new URL(url);
    if (u.password) u.password = '***';
    if (u.username) u.username = u.username.replace(/.(?=.{0,0}$)/g, '*'); // keep username visible-ish
    return u.toString();
  } catch {
    // Not a parseable URL — fall back to a coarse regex mask.
    return url.replace(/:\/\/([^:]+):([^@]+)@/, '://$1:***@');
  }
}

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory does not exist: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort(); // lexicographic ordering ensures predictable apply order
}

function resolveDatabaseUrl() {
  const env = parseEnvFile(ENV_FILE);
  const url = env.DATABASE_URL;

  if (!url) {
    throw new Error(`DATABASE_URL is not defined in ${ENV_FILE}`);
  }

  return url;
}

function main() {
  // 1. Resolve connection string.
  let databaseUrl;
  try {
    databaseUrl = resolveDatabaseUrl();
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  console.log(`Loaded DATABASE_URL from ${path.relative(process.cwd(), ENV_FILE)}`);
  console.log(`Connected successfully to ${redactUrl(databaseUrl)}`);

  // 2. Discover migrations.
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log(`No SQL migration files found in ${MIGRATIONS_DIR}`);
    return;
  }

  console.log(`Found ${files.length} migration(s) in ${MIGRATIONS_DIR}:`);
  files.forEach((file, index) => {
    const num = String(index + 1).padStart(String(files.length).length, '0');
    console.log(`  [${num}] would apply: ${file}`);
  });
}

main();

