#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Minimal .env parser. Reads KEY=VALUE lines, ignores comments and blanks.
 * We deliberately only return the keys the script needs (DATABASE_URL),
 * so unrelated secrets in the file are never held in memory longer than
 * the parse itself.
 */
function loadDatabaseUrl(envPath) {
  if (!fs.existsSync(envPath)) {
    console.error(`Error: env file not found at ${envPath}`);
    process.exit(1);
  }

  const contents = fs.readFileSync(envPath, 'utf8');
  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eq = line.indexOf('=');
    if (eq === -1) continue;

    const key = line.slice(0, eq).trim();
    if (key !== 'DATABASE_URL') continue; // ignore everything else

    let value = line.slice(eq + 1).trim();
    // Strip surrounding quotes if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    return value;
  }

  return null;
}

/**
 * Build a safe, log-friendly description of the connection target.
 * Never returns the password or full URL — only scheme, host, port, and
 * database name. Username is masked to its first character.
 */
function describeConnection(urlString) {
  try {
    const u = new URL(urlString);
    const user = u.username ? `${u.username[0]}***` : '(no user)';
    const host = u.hostname || '(no host)';
    const port = u.port || '(default port)';
    const db = u.pathname && u.pathname !== '/' ? u.pathname.slice(1) : '(no db)';
    const scheme = u.protocol.replace(':', '');
    return `${scheme}://${user}@${host}:${port}/${db}`;
  } catch {
    // If parsing fails, don't fall back to printing the raw URL.
    return '(unparseable DATABASE_URL — value redacted)';
  }
}

function migrate() {
  // 1. Resolve connection string
  const databaseUrl = loadDatabaseUrl(ENV_FILE);
