      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

/**
 * Returns a safe, loggable description of a connection string:
 * the scheme and (if present) host/port/database — but never the
 * userinfo (user:password) component.
 */
function describeConnection(urlString) {
  try {
    const u = new URL(urlString);
    const scheme = u.protocol.replace(/:$/, '');
    const host = u.hostname || '<unknown-host>';
    const port = u.port ? `:${u.port}` : '';
    const db = u.pathname && u.pathname !== '/' ? u.pathname : '';
    return `${scheme}://${host}${port}${db}`;
  } catch {
    // Don't fall back to printing the raw string — it may contain secrets.
    return '<unparseable connection string>';
